const BYTES_PER_MB = 1024 * 1024;
const IN_CHUNK = 500;

function chunks<T>(items: readonly T[]): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += IN_CHUNK) {
    out.push(items.slice(i, i + IN_CHUNK));
  }
  return out;
}

/**
 * Permanently deletes up to `limit` issues archived at or before `cutoff`,
 * with their labels links, comments and attachments, in one transaction. The
 * project's number high-water mark is raised first so numbers are never reused.
 */
export async function purgeExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
  limit: number,
): Promise<PurgedIssues> {
  return getDb().transaction((tx) => {
    const expired = tx
      .select({
        id: issues.id,
        projectId: issues.projectId,
        number: issues.number,
      })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          isNotNull(issues.archivedAt),
          lte(issues.archivedAt, cutoff),
        ),
      )
      .orderBy(issues.id)
      .limit(limit)
      .all();

    if (expired.length === 0) {
      return { issueIds: [], commentIds: [], freedMb: 0 };
    }

