/**
 * Permanently deletes up to `limit` issues archived at or before `cutoff`,
 * with their labels links, comments and attachments, in one transaction. The
 * project's number high-water mark is raised first so numbers are never reused.
 */
export async function purgeExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
  limit: number,
): Promise<PurgedIssues> {
  return getDb().transaction((tx) => {
    const expired = tx
      .select({
        id: issues.id,
        projectId: issues.projectId,
        number: issues.number,
      })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          isNotNull(issues.archivedAt),
          lte(issues.archivedAt, cutoff),
        ),
      )
      .orderBy(issues.id)
      .limit(limit)
      .all();

    if (expired.length === 0) {
      return { issueIds: [], commentIds: [], freedMb: 0 };
    }

    const highest = new Map<string, number>();
    for (const row of expired) {
      highest.set(row.projectId, Math.max(highest.get(row.projectId) ?? 0, row.number));
    }
    for (const [projectId, lastNumber] of highest) {
      tx.insert(projectIssueCounters)
        .values({ projectId, orgId, lastNumber })
        .onConflictDoUpdate({
          target: projectIssueCounters.projectId,
          set: {
            lastNumber: sql`max(${projectIssueCounters.lastNumber}, ${lastNumber})`,
          },
        })
        .run();
    }

    const ids = expired.map((row) => row.id as IssueId);
    const commentIds: string[] = [];
    let freedMb = 0;

    for (const part of chunks(ids)) {
      const commentRows = tx
        .select({ id: comments.id })
        .from(comments)
        .where(
          and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, part)),
        )
        .all();
      commentIds.push(...commentRows.map((row) => row.id));

      const sizes = tx
        .select({ sizeBytes: attachments.sizeBytes })
        .from(attachments)
        .where(
          and(
            orgPredicate(attachments.orgId, orgId),
            inArray(attachments.issueId, part),
          ),
        )
        .all();
      for (const size of sizes) freedMb += Math.ceil(size.sizeBytes / BYTES_PER_MB);

      tx.delete(attachments)
        .where(
          and(
            orgPredicate(attachments.orgId, orgId),
            inArray(attachments.issueId, part),
          ),
        )
        .run();
      tx.delete(comments)
        .where(
          and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, part)),
        )
        .run();
      tx.delete(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            inArray(issueLabels.issueId, part),
          ),
        )
        .run();
      tx.delete(issues)
        .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, part)))
        .run();
    }

    return { issueIds: ids, commentIds, freedMb };
  });
}

